insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g5_science_v1'
from (values
('112.7.b.6.A',2,'A student wants to find out which of three objects has the most mass. Which tool should the student use?','["a balance", "a thermometer", "a magnet", "a hand lens"]'::jsonb,0,'A balance compares mass.','original'),
('112.7.b.6.A',3,'A steel paper clip is pulled toward a magnet, but a plastic button is not. Which property is being compared?','["volume", "magnetism", "solubility", "physical state"]'::jsonb,1,'The objects are sorted by how they react to a magnet.','original'),
('112.7.b.6.A',3,'A student pours 50 mL of water into a graduated cylinder. What property is the student measuring?','["density", "mass", "volume", "magnetism"]'::jsonb,2,'A graduated cylinder measures the volume of a liquid.','original'),
('112.7.b.6.A',3,'Salt dissolves in water, but sand does not. Which property is being compared?','["magnetism", "mass", "physical state", "solubility in water"]'::jsonb,3,'Solubility is the ability to dissolve in a liquid.','original'),
('112.7.b.6.A',3,'A wooden spoon and a metal spoon are placed in hot soup. After a minute the metal handle is much hotter. What does this show?','["metal conducts thermal energy better than wood", "metal has less mass than wood", "wood conducts thermal energy better than metal", "wood is magnetic"]'::jsonb,0,'Metal is a better thermal conductor.','original'),
('112.7.b.6.A',4,'A student places four objects in water. Object W sinks, Object X floats, Object Y floats, and Object Z sinks. Which two objects are probably LESS dense than water?','["Y and Z", "X and Y", "W and X", "W and Z"]'::jsonb,1,'Objects that float are less dense than water.','original'),
('112.7.b.6.A',3,'Which substance is a liquid at room temperature?','["wood", "copper", "milk", "helium"]'::jsonb,2,'Milk is a liquid; copper and wood are solids, and helium is a gas.','original'),
('112.7.b.6.B',2,'A mixture contains iron filings and sand. Which tool could separate the iron filings?','["a balance", "a thermometer", "a ruler", "a magnet"]'::jsonb,3,'Iron is attracted to a magnet and sand is not.','original'),
('112.7.b.6.B',3,'When iron filings and sand are mixed, what happens to the properties of each substance?','["each keeps its own properties", "both change into a new substance", "the iron stops being magnetic", "both lose their mass"]'::jsonb,0,'In a mixture the substances keep their properties.','original'),
('112.7.b.6.B',3,'Sand is stirred into water. How could the sand be separated again?','["add more sand", "pour the mixture through a filter", "freeze the mixture", "shine a light on it"]'::jsonb,1,'A filter traps the sand pieces.','original'),
('112.7.b.6.B',3,'A bag holds small beads and large marbles. What could be used to separate them?','["a thermometer", "a candle", "a strainer with holes between the sizes", "a magnet"]'::jsonb,2,'A strainer lets small pieces through and holds the large ones.','original'),
('112.7.b.6.B',3,'A student mixes salt and pepper in a bowl. Which statement is true?','["the salt turned into pepper", "the mass of both disappeared", "a new substance was made", "both substances are still in the bowl and keep their properties"]'::jsonb,3,'A mixture does not form a new substance.','original'),
('112.7.b.6.B',4,'A mixture of iron filings, sand, and water is poured through a filter, and then a magnet is held over the sand left on the filter. What will the magnet pick up?','["the iron filings", "nothing", "the sand", "the water"]'::jsonb,0,'Only the iron is attracted to a magnet.','original'),
('112.7.b.6.B',3,'Which is a mixture whose parts can easily be seen?','["an aluminum can", "a salad", "a gold bar", "pure water"]'::jsonb,1,'The ingredients of a salad can each be seen.','original'),
('112.7.b.6.C',3,'A student stirs 30 g of sugar into 170 g of water until it dissolves. What is the mass of the solution?','["140 g", "170 g", "200 g", "30 g"]'::jsonb,2,'Matter is conserved, so 30 g plus 170 g is 200 g.','original'),
('112.7.b.6.C',3,'After salt dissolves in water, how can a student show the salt is still in the solution?','["look for the salt with a magnet", "freeze the solution", "weigh only the cup", "let the water evaporate and look for the salt"]'::jsonb,3,'When the water evaporates, the salt is left behind.','original'),
('112.7.b.6.C',3,'Drink powder is stirred into water. Which properties of the water change?','["its color and taste", "its mass is destroyed", "it stops being a liquid", "it becomes a solid"]'::jsonb,0,'The solution can look and taste different.','original'),
('112.7.b.6.C',3,'A student weighs a cup of water and a spoonful of salt separately, then dissolves the salt in the water. What should the total mass do?','["go up", "stay the same", "go down", "become zero"]'::jsonb,1,'Mass is conserved when a solution forms.','original'),
('112.7.b.6.C',4,'A student has a 150 g solution after dissolving 25 g of sugar in water. How much water did the student start with?','["150 g", "175 g", "125 g", "25 g"]'::jsonb,2,'150 g minus 25 g leaves 125 g.','original'),
('112.7.b.6.C',3,'Which is a solution?','["sand stirred into water", "pebbles in a bucket", "oil floating on water", "salt completely dissolved in water"]'::jsonb,3,'A solution is evenly mixed, with the substance dissolved.','original'),
('112.7.b.6.C',4,'Which statement about dissolving is true?','["the dissolved matter is still there even though it can not be seen", "dissolving creates new matter", "the dissolved matter is gone", "dissolving removes mass from the water"]'::jsonb,0,'Matter is conserved when it dissolves.','original'),
('112.7.b.6.D',2,'What is matter made of?','["light", "particles too small to see", "only large grains", "empty space only"]'::jsonb,1,'All matter is made of tiny particles.','original'),
('112.7.b.6.D',3,'A balloon fills up with air and gets bigger. What does this show?','["air is not matter", "air is made of liquid", "air is made of particles that take up space", "air has no mass at all"]'::jsonb,2,'Air particles take up space and push on the balloon.','original'),
('112.7.b.6.D',3,'A smell from baking cookies spreads across a house. What does this suggest?','["air is empty", "the cookies left the oven", "smells are solid", "tiny particles are moving through the air"]'::jsonb,3,'The particles of scent spread through the air.','original'),
('112.7.b.6.D',3,'A drop of food coloring slowly spreads through a glass of water. Why?','["the particles of dye and water move and mix", "the dye is destroyed", "the glass pulls the dye", "the water becomes a solid"]'::jsonb,0,'Moving particles mix together.','original'),
('112.7.b.6.D',3,'Which can NOT be seen but is still matter?','["a rock", "the air inside a balloon", "a pencil", "a wooden chair"]'::jsonb,1,'Air is matter, but its particles are too small to see.','original'),
('112.7.b.6.D',3,'A model uses small beads to show the particles in a solid, liquid, and gas. In which state would the beads be the farthest apart?','["solid", "liquid", "gas", "they are all the same"]'::jsonb,2,'Gas particles are spread out the most.','original'),
('112.7.b.6.D',4,'A student squeezes air in a closed syringe. The plunger moves in a little. What does this show?','["the syringe makes the air a solid", "air particles are destroyed", "air has no particles", "there is space between the particles of air"]'::jsonb,3,'The particles can be pushed closer together.','original'),
('112.7.b.7.A',2,'Two students push on opposite sides of a box with the same force. What happens to the box?','["it does not move", "it speeds up", "it flies up", "it moves toward one student"]'::jsonb,0,'Equal forces in opposite directions balance.','original'),
('112.7.b.7.A',3,'A student pushes a cart with a force of 10 N and another student pushes the other way with 4 N. What happens?','["the cart moves toward the smaller force", "the cart moves in the direction of the larger force", "the cart disappears", "the cart stays still"]'::jsonb,1,'Unequal forces cause motion in the direction of the greater force.','original'),
('112.7.b.7.A',3,'A soccer ball is kicked and rolls across the grass. Eventually it stops. Which force slows it?','["magnetism", "light", "friction", "gravity pushing it sideways"]'::jsonb,2,'Friction acts against the motion.','original'),
('112.7.b.7.A',3,'A moving cart hits a stationary cart and the stationary cart begins to move. What happened to the energy?','["energy turned into matter", "energy stayed only in the first cart", "energy was destroyed", "some energy transferred to the second cart"]'::jsonb,3,'Energy transfers during a collision.','original'),
('112.7.b.7.A',3,'A tug-of-war is tied, with neither team moving. What does this tell you about the forces?','["the forces on each side are equal", "one side is much stronger", "there are no forces", "gravity is missing"]'::jsonb,0,'Balanced forces produce no change in motion.','original'),
('112.7.b.7.A',3,'Which change would make a toy car roll faster down a ramp?','["making the ramp flatter", "making the ramp steeper", "making the ramp rougher", "adding sand to the ramp"]'::jsonb,1,'A steeper ramp lets gravity speed the car up more.','original'),
('112.7.b.7.A',4,'A student pushes a box with 20 N. The floor pushes back with 20 N of friction. What is the motion of the box?','["it moves backward", "it speeds up quickly", "it moves at a steady speed or stays still", "it floats"]'::jsonb,2,'Equal opposite forces are balanced.','original'),
('112.7.b.7.B',3,'A student tests how ramp height affects how far a toy car rolls. Which should be the ONE thing the student changes?','["the size of the car", "the person who releases the car", "the floor surface", "the height of the ramp"]'::jsonb,3,'Only one variable should be changed.','original'),
('112.7.b.7.B',3,'In a balloon rocket investigation, which is a good variable to keep the same?','["the length of the string", "the balloon size for every trial", "the amount of air in each trial", "the time of day"]'::jsonb,0,'Keeping other conditions equal makes the test fair.','original'),
('112.7.b.7.B',3,'A student wants to test whether a heavier cart travels farther down a ramp. What should the student measure?','["the age of the cart", "the distance the cart travels", "the color of the cart", "the sound the cart makes"]'::jsonb,1,'Distance traveled is the outcome being measured.','original'),
('112.7.b.7.B',3,'Why should a student do several trials in a force experiment?','["to waste time", "to avoid recording data", "to make sure the results are reliable", "to change the question"]'::jsonb,2,'Repeated trials improve reliability.','original'),
('112.7.b.7.B',3,'A student releases a cart from the top of a ramp each time. What is the benefit?','["the ramp stops moving", "the data become unnecessary", "the cart will never stop", "the starting point stays the same"]'::jsonb,3,'A constant starting point keeps the test fair.','original'),
('112.7.b.7.B',4,'A student records the distance a balloon rocket travels with different amounts of air. Which table heading is MOST useful?','["amount of air and distance traveled", "time of day and weather", "name of student and date", "color of balloon and shape of room"]'::jsonb,0,'A data table should show the changed variable and the measured result.','original'),
('112.7.b.7.B',4,'Which question can be tested with a car on a ramp?','["Which color car is prettiest?", "Does a steeper ramp make the car go farther?", "Why was the car made?", "Which ramp do students like?"]'::jsonb,1,'A testable question can be answered with measurements.','original'),
('112.7.b.8.A',2,'A flashlight battery stores what kind of energy?','["magnetic energy", "sound energy", "chemical energy", "thermal energy only"]'::jsonb,2,'Batteries store chemical energy.','original'),
